INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob jede Datenstruktur nur einen Elternknoten hat?', 2, '[{"text": "Ja", "correct": true, "because": "Typisch für Baumstrukturen"}, {"text": "Nein", "correct": false, "because": "Ein Elternknoten ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal ist entscheidend, wenn ich Daten in einer Baumstruktur speichere?', 3, '[{"text": "Eltern-Kind-Beziehung", "correct": true, "because": "Definiert die Hierarchie"}, {"text": "Flache Tabelle", "correct": false, "because": "Nicht hierarchisch"}, {"text": "Zufällige Reihenfolge", "correct": false, "because": "Kein Strukturmerkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Szenarien passen gut zu einer strukturierten Datenorganisation?', 5, '[{"text": "Organisationsstruktur", "correct": true, "because": "Spiegelt Abteilungen wider"}, {"text": "Dateisysteme", "correct": true, "because": "Verzeichnisse hierarchisch"}, {"text": "Unstrukturierte Texte", "correct": false, "because": "Keine Hierarchie"}, {"text": "Einfache Listen", "correct": false, "because": "Flach, nicht hierarchisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Daten haben eine feste Hierarchie. b) Mehrere Elternknoten sind möglich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nur ein Elternknoten erlaubt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich eine Baumstruktur für Daten entwerfe?', 4, '[{"text": "Knotenverbindungen", "correct": false, "because": "Definieren die Struktur"}, {"text": "Hierarchieebenen", "correct": false, "because": "Bestimmen Ordnung"}, {"text": "Farbschema", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass solche Strukturen immer schneller als relationale Tabellen sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig vom Anwendungsfall"}, {"text": "Ja", "correct": false, "because": "Nicht universell schneller"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich, um Daten in einer Baumstruktur zu durchsuchen?', 3, '[{"text": "Tiefensuche", "correct": true, "because": "Folgt Hierarchie effizient"}, {"text": "Lineare Suche", "correct": false, "because": "Ignoriert Struktur"}, {"text": "Zufällige Auswahl", "correct": false, "because": "Ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen eine strukturierte Datenbank effektiv?', 5, '[{"text": "Eindeutige Elternknoten", "correct": true, "because": "Klar definierte Hierarchie"}, {"text": "Schnelle Traversierung", "correct": true, "because": "Effiziente Abfragen"}, {"text": "Flache Struktur", "correct": false, "because": "Nicht hierarchisch"}, {"text": "Zufällige Verknüpfungen", "correct": false, "because": "Verwirrt Ordnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) jede Ebene nur ein Kind hat und b) Daten leicht verschoben werden können. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "Mehrere Kinder möglich, Verschiebung komplex"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beide falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Daten in einer Baumstruktur zu speichern?', 4, '[{"text": "Elternknoten", "correct": false, "because": "Definiert Hierarchie"}, {"text": "Kindknoten", "correct": false, "because": "Teil der Struktur"}, {"text": "Bildschirmgröße", "correct": true, "because": "Kein Datenfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind solche Strukturen flexibel bei Änderungen?', 2, '[{"text": "Nein", "correct": true, "because": "Änderungen oft aufwendig"}, {"text": "Ja", "correct": false, "because": "Feste Hierarchie"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Baumstruktur für Daten?', 4, '[{"text": "Klare Ordnung", "correct": true, "because": "Logische Hierarchie"}, {"text": "Schnelle Abfragen", "correct": true, "because": "Effiziente Traversierung"}, {"text": "Maximale Flexibilität", "correct": false, "because": "Eher starr"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass sie nur für kleine Datenmengen geeignet sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Skalierbar mit Optimierung"}, {"text": "Ja", "correct": false, "because": "Auch für große Sets nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich Daten hierarchisch organisiere?', 3, '[{"text": "Logische Strukturierung", "correct": true, "because": "Klarheit in Beziehungen"}, {"text": "Maximale Datenmenge", "correct": false, "because": "Nicht primär"}, {"text": "Einfache Tabellen", "correct": false, "because": "Nicht hierarchisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Daten haben eine Wurzel. b) Sie erlauben Zyklen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zyklen nicht möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik wähle ich, um eine Hierarchie zu durchlaufen?', 4, '[{"text": "Breitensuche", "correct": true, "because": "Ebene für Ebene effizient"}, {"text": "Zufällige Suche", "correct": false, "because": "Ineffizient"}, {"text": "Sortierung", "correct": false, "because": "Anderer Zweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob jede Ebene mehrere Kinder haben kann?', 2, '[{"text": "Ja", "correct": true, "because": "Typisch für Hierarchien"}, {"text": "Nein", "correct": false, "because": "Mehrere Kinder erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen eine Baumstruktur nützlich?', 5, '[{"text": "Eindeutige Beziehungen", "correct": true, "because": "Klar definierte Ordnung"}, {"text": "Einfache Navigation", "correct": true, "because": "Logische Traversierung"}, {"text": "Hohe Flexibilität", "correct": false, "because": "Eher starr"}, {"text": "Flache Daten", "correct": false, "because": "Nicht hierarchisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind solche Strukturen für relationale Daten ideal?', 3, '[{"text": "Nein", "correct": true, "because": "Besser für feste Hierarchien"}, {"text": "Ja", "correct": false, "because": "Relationale Modelle flexibler"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt am besten zu einer Baumstruktur?', 4, '[{"text": "Verwaltung von Abteilungen", "correct": true, "because": "Klar hierarchisch"}, {"text": "Unstrukturierte Logs", "correct": false, "because": "Keine Hierarchie"}, {"text": "Flache Tabellen", "correct": false, "because": "Nicht hierarchisch"}]');
